<?php require_once "config/database.php";require_once "includes/functions.php";$pageTitle="Register";$err="";if($_SERVER["REQUEST_METHOD"]==="POST"){$n=trim($_POST["name"]??"");$em=trim($_POST["email"]??"");$pw=$_POST["password"]??"";if(!$n||!filter_var($em,FILTER_VALIDATE_EMAIL)||strlen($pw)<6)$err="Use a valid name/email and a password of at least 6 characters.";else{try{$s=$pdo->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'customer')");$s->execute([$n,$em,password_hash($pw,PASSWORD_DEFAULT)]);flash("success","Registration successful.");go("login.php");}catch(PDOException $e){$err="Email is already registered.";}}}require "includes/header.php";?><section class="section"><div class="container formwrap"><div class="eyebrow">Join Rasit</div><h1>Create Account</h1><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><form class="panel" method="post"><div class="group"><label>Name</label><input class="input" name="name" required></div><div class="group"><label>Email</label><input class="input" type="email" name="email" required></div><div class="group"><label>Password</label><input class="input" type="password" name="password" minlength="6" required></div><button class="btn">Register</button></form></div></section><?php require "includes/footer.php";?>